  const ATT_OK = /\.(png|jpe?g|gif|webp|pdf|docx|xlsx|csv|txt|pptx|msg|eml)$/i;
  async function tkUpload(id, file) {
    const t = I().get('task', id); if (!t || !canEdit()) return; if (!ATT_OK.test(file.name)) { toast('That file type cannot be attached. Use an image, PDF, Word, Excel, CSV, text or mail file.', 6000, true); return; } if (file.size > 20e6) { toast('The file is larger than 20 MB', 5000, true); return; }
    V.loading(true, 'Attaching ' + file.name + '…');
    try {
      const rec = await API.uploadFile(S.project.id, file, 'task_attachment', { task: id }); const fid = rec && (rec.id || rec.fileId); if (!fid) throw new Error('The file was not saved');
      const cur = I().get('task', id) || t; await save(cur, { attachments: (cur.attachments || []).concat([{ id: fid, name: file.name, size: file.size, at: new Date().toISOString(), by: (S.user && (S.user.name || S.user.email)) || '' }]) });
      toast('Attached ' + file.name, 3500); if (S.ui.view === 'taskpage') V.render(); else taskForm(I().get('task', id), 'details');
    } catch (e) { toast(e.message || 'The file could not be attached', 6000, true); } finally { V.loading(false); }
  }
  const openTaskId = () => { const b = document.querySelector('[data-act="tkSave"][data-id]'); return b ? b.getAttribute('data-id') : ''; };
  ACT.tkAttachFile = async () => { const id = openTaskId(); if (!id) { toast('Save the task first, then attach files to it'); return; } const fs = (await V.pickFile('.png,.jpg,.jpeg,.gif,.webp,.pdf,.docx,.xlsx,.csv,.txt,.pptx,.msg,.eml', true)) || []; for (const f of fs) await tkUpload(id, f); };
  ACT.tkFileOpen = async a => { try { const b = await V.fileBlob(a.getAttribute('data-fid')); const url = URL.createObjectURL(b); const w = window.open(url, '_blank'); if (!w) toast('Your browser blocked the new tab. Allow pop-ups for this site.', 6000, true); setTimeout(() => URL.revokeObjectURL(url), 60000); } catch (e) { toast('The file could not be opened', 5000, true); } };
  ACT.tkFileDel = async a => { const id = openTaskId(); const t = I().get('task', id); if (!t || !(await V.confirmDialog('Remove attachment', 'Remove this file from the task?', 'Remove', true))) return; await save(t, { attachments: (t.attachments || []).filter(x => x.id !== a.getAttribute('data-fid')) }); if (S.ui.view === 'taskpage') V.render(); else taskForm(I().get('task', id), 'details'); };
