  document.addEventListener('paste', e => {
    const id = openTaskId(); if (!id || !canEdit()) return; const items = [...((e.clipboardData && e.clipboardData.items) || [])].filter(i => i.kind === 'file' && /^image\//.test(i.type)); if (!items.length) return;
    e.preventDefault(); const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-'); items.forEach((it, n) => { const f = it.getAsFile(); if (f) tkUpload(id, new File([f], 'screenshot-' + stamp + (n ? '-' + (n + 1) : '') + '.png', { type: f.type || 'image/png' })); });
  });
