  ACT.tkClaudeAdd = a => { const id = a.getAttribute('data-id'); const action = (document.getElementById('tkClA') || {}).value || 'explain'; const question = ((document.getElementById('tkAiQ') || {}).value || '').trim(); if (action === 'ask' && !question) { toast('Type your question above first'); return; } S.ui.tkCl = { id, action, question, prompt: '' }; const o = document.getElementById('tkAiOut'); if (o) o.innerHTML = `<div class="notice"><span>Paste the whole reply Claude gave you for "${esc(action === 'checklist' ? 'Generate checklist' : (AI_LABEL[action] || action))}".</span></div><textarea id="tkClR" rows="8" placeholder="Paste Claude's reply here"></textarea><div class="row" style="gap:8px;margin-top:8px"><button type="button" class="btn sm primary" data-act="tkClaudeBack" data-id="${esc(id)}">Bring the reply back</button></div>`; };
