  // ---------- AI type suggestions (by intent; ambiguous ones are left for a person) ----------
  async function classify(list) { const r = await API.post(`/api/projects/${S.project.id}/tasks/classify`, { items: list.map(t => ({ title: t.title, desc: t.desc || '' })) }); return r; }
  ACT.tkClassifyOne = a => V.busy(a, async () => { const title = (g('tkf_t') || '').trim(); if (!title) { toast('Write the title first'); return; } try { const r = await classify([{ title, desc: g('tkf_d') }]); const x = r.items[0];
      if (x.type) { document.getElementById('tkf_ty').value = x.type; ACT.tkTypeChg(document.getElementById('tkf_ty')); } toast((x.type ? 'Suggested: ' + x.type : 'No clear type') + (x.ambiguous ? ' (ambiguous' + (x.alt ? ', could be ' + x.alt : '') + ')' : '') + (x.reason ? '. ' + x.reason : '') + ' · ' + r.provider + '. Check before saving.', 9000); } catch (e) { toast(e.message, 6000, true); } });
