  ACT.tkExtractAdd = a => { const text = (document.getElementById('tkx_t').value || '').trim(); const label = (document.getElementById('tkx_l').value || '').trim() || 'Meeting transcript'; if (text.length < 40) { toast('Paste or choose the transcript first, so the reply can be checked against it'); return; } const parts = exParts(text); S.ui.tkxC = { parts, i: 0, items: [], notes: [], label, prompt: '' }; exClaudeStep(); };
